insert into public.site_settings (setting_key, setting_value) values ('hero', '{"title":"من مجرد فكرة.. إلى مشروع رقمي متكامل.","subtitle":"نصمم المواقع، ونبني الأنظمة الذكية، وننتج المحتوى والفيديوهات، ونحول البيانات إلى قرارات.. كل ذلك تحت سقف واحد.","video_url":"/videos/hero.mp4","poster_url":"/images/hero-poster.jpg"}'::jsonb) on conflict (setting_key) do nothing;
insert into public.site_settings (setting_key, setting_value) values ('banner', '{"enabled":false,"text":""}'::jsonb) on conflict (setting_key) do nothing;
insert into public.site_settings (setting_key, setting_value) values ('faq', '[{"q":"ما الخدمات التي تقدمها التزام؟","a":"تصميم المواقع والمتاجر، صناعة المحتوى بالذكاء الاصطناعي، تحليل البيانات وPower BI، الأتمتة والأنظمة الذكية، إنشاء السير الذاتية، وإنتاج فيديوهات الأعمال."},{"q":"هل يمكن تصميم موقع حسب فكرة خاصة؟","a":"نعم، كل مشروع يُبنى حسب فكرتك واحتياجك. أرسل الفكرة من صفحة الخدمة وسنراجعها معك."},{"q":"هل يوجد تجربة مجانية؟","a":"نعم، عند إنشاء حساب تبدأ تجربة مجانية للوظائف التجريبية المحددة في كل خدمة."},{"q":"ما مدة التجربة المجانية؟","a":"24 ساعة تبدأ من وقت تأكيد التسجيل على الخادم، ويظهر لك عداد الوقت المتبقي في لوحة التحكم."},{"q":"كيف أطلب خدمة؟","a":"اختر الخدمة، املأ نموذج الطلب وأرفق ملفاتك، ثم تابع حالة الطلب من لوحة العميل."},{"q":"كيف يتم تسعير المشاريع؟","a":"بعد مراجعة الطلب نرسل لك عرض سعر حسب نطاق العمل والباقة المناسبة، ولا يبدأ التنفيذ إلا بعد موافقتك."},{"q":"هل يمكن إنشاء CV باللغة الإنجليزية؟","a":"نعم، يدعم استوديو السيرة الذاتية العربية والإنجليزية وقوالب متوافقة مع ATS."},{"q":"هل يمكن إنتاج فيديو إعلاني؟","a":"نعم، نستقبل طلبات الفيديو ونجهز الفكرة والسيناريو والـ Storyboard ثم ننفذ الإنتاج ونسلمه بالمقاس المطلوب."},{"q":"هل يمكن تحليل ملفات Excel؟","a":"نعم، يمكنك رفع ملفات CSV وExcel ومعاينتها وتحديد هدف التحليل وإرسال الطلب."},{"q":"كيف أتابع تنفيذ مشروعي؟","a":"من لوحة العميل: مراحل المشروع، التحديثات، الملفات، الرسائل، وطلبات التعديل والاعتماد."},{"q":"ما طرق التواصل؟","a":"واتساب ونموذج التواصل والرسائل داخل لوحة العميل."},{"q":"هل يمكن تعديل المشروع بعد التسليم؟","a":"نعم ضمن عدد التعديلات المحدد في الباقة، ويمكن طلب تعديلات إضافية بعرض سعر."}]'::jsonb) on conflict (setting_key) do nothing;
insert into public.site_settings (setting_key, setting_value) values ('about', '"التزام منصة رقمية متخصصة في تصميم المواقع وتطوير الحلول الذكية وتحليل البيانات وإنتاج المحتوى والفيديوهات باستخدام أحدث تقنيات الذكاء الاصطناعي.\n\nبإدارة المهندس أحمد زهران، نعمل على تحويل الأفكار إلى حلول رقمية عملية، بداية من التخطيط والتصميم وحتى التطوير والتنفيذ والتسليم.\n\nنؤمن بأن كل فكرة تستحق أن تتحول إلى مشروع ناجح، ونعمل على تسهيل الوصول إلى التكنولوجيا والحلول الرقمية بطريقة احترافية."'::jsonb) on conflict (setting_key) do nothing;
insert into public.site_settings (setting_key, setting_value) values ('cv_templates', '[{"id":"ats","name":"ATS بسيط","active":true},{"id":"professional","name":"Professional","active":true},{"id":"creative","name":"Creative","active":true},{"id":"executive","name":"Executive","active":true}]'::jsonb) on conflict (setting_key) do nothing;
insert into public.site_settings (setting_key, setting_value) values ('video_templates', '["شركات","مقاولات","مطاعم","متاجر","عقارات","تعليم"]'::jsonb) on conflict (setting_key) do nothing;
insert into public.site_settings (setting_key, setting_value) values ('privacy_policy', '"مسودة سياسة الخصوصية — يجب مراجعتها قبل الإطلاق.\n\nنجمع البيانات التي تقدمها عند التسجيل وطلب الخدمات (الاسم، البريد، الهاتف، ملفات المشروع) لاستخدامها في تقديم الخدمة والتواصل معك فقط. لا نبيع بياناتك ولا نشاركها إلا مع مزودي الخدمات اللازمين للتشغيل (الاستضافة وقاعدة البيانات ومزودي الذكاء الاصطناعي عند استخدامك لهذه الميزات). لا نخزن بيانات البطاقات البنكية. يمكنك طلب حذف حسابك وبياناتك بالتواصل معنا."'::jsonb) on conflict (setting_key) do nothing;
insert into public.site_settings (setting_key, setting_value) values ('terms_of_service', '"مسودة الشروط والأحكام — يجب مراجعتها قبل الإطلاق.\n\nالتجربة المجانية مدتها 24 ساعة وتشمل وظائف تجريبية محدودة. لا يتحول الحساب إلى اشتراك مدفوع تلقائيًا. يبدأ تنفيذ أي مشروع بعد الموافقة على عرض السعر وتأكيد الدفع من الإدارة. عدد التعديلات ومدة التنفيذ حسب الباقة المتفق عليها. المحتوى المُولد بالذكاء الاصطناعي يخضع لمراجعتك قبل الاعتماد، ولا يضيف بيانات أو مؤهلات لم تقدمها."'::jsonb) on conflict (setting_key) do nothing;
insert into public.site_settings (setting_key, setting_value) values ('courses', '[{"id":"pm","title":"إدارة المشاريع الاحترافية والتأهيل لاختبار PMP","title_en":"Professional Project Management & PMP Prep","category":"management","level":"متوسط","hours":35,"description":"مبادئ إدارة المشاريع وفق دليل PMBOK: النطاق والجدولة والتكلفة والمخاطر وأصحاب المصلحة، مع أسئلة تدريبية للتأهيل لاختبار PMP. (شهادة إتمام من التزام، وليست شهادة PMI الرسمية).","active":true},{"id":"agile","title":"إدارة المشاريع الرشيقة Agile وScrum","title_en":"Agile & Scrum Project Management","category":"management","level":"مبتدئ","hours":16,"description":"أطر العمل الرشيقة، أدوار Scrum، إدارة الـ Backlog والـ Sprints عمليًا.","active":true},{"id":"p6","title":"تخطيط وجدولة المشاريع Primavera P6 وMS Project","title_en":"Project Planning with Primavera P6 & MS Project","category":"engineering","level":"متوسط","hours":24,"description":"إعداد البرنامج الزمني وتحميل الموارد ومتابعة التقدم وتقارير الإنجاز للمشاريع الهندسية.","active":true},{"id":"contracts","title":"الإدارة الهندسية وإدارة عقود المقاولات","title_en":"Engineering Management & Construction Contracts","category":"engineering","level":"متوسط","hours":20,"description":"إدارة العقود والمستخلصات وأوامر التغيير والمطالبات ومتابعة المقاولين.","active":true},{"id":"ta","title":"التحليل الفني للأسواق المالية","title_en":"Technical Analysis of Financial Markets","category":"finance","level":"مبتدئ","hours":20,"description":"الشموع اليابانية والاتجاهات والدعوم والمقاومات والمؤشرات الفنية وإدارة المخاطر. (محتوى تعليمي وليس توصيات استثمارية).","active":true},{"id":"fa","title":"التحليل المالي وقراءة القوائم المالية","title_en":"Financial Analysis & Financial Statements","category":"finance","level":"متوسط","hours":20,"description":"قراءة الميزانية وقائمة الدخل والتدفقات النقدية، النسب المالية، وتقييم أداء الشركات.","active":true},{"id":"webai","title":"تصميم وتخطيط المواقع وربطها بالذكاء الاصطناعي","title_en":"Website Design & Planning Integrated with AI","category":"tech","level":"مبتدئ","hours":24,"description":"تخطيط الموقع وتجربة المستخدم، بناء الصفحات، والنشر على Netlify، وربط الموقع بأدوات الذكاء الاصطناعي ونماذج المحادثة.","active":true},{"id":"vibe","title":"Vibe Coding: البرمجة بمساعدة الذكاء الاصطناعي","title_en":"Vibe Coding: Building Software with AI","category":"tech","level":"مبتدئ","hours":18,"description":"بناء تطبيقات ومواقع حقيقية بالحوار مع أدوات الذكاء الاصطناعي مثل Claude Code، ومراجعة الكود ونشره بأمان.","active":true},{"id":"prog","title":"أساسيات البرمجة Python وJavaScript","title_en":"Programming Fundamentals: Python & JavaScript","category":"tech","level":"مبتدئ","hours":30,"description":"المتغيرات والدوال وهياكل البيانات وبناء مشاريع صغيرة عملية.","active":true},{"id":"powerbi","title":"Power BI وتحليل البيانات للإدارة","title_en":"Power BI & Data Analysis for Managers","category":"data","level":"متوسط","hours":20,"description":"تنظيف البيانات وبناء النماذج ولوحات المؤشرات KPIs والتقارير التفاعلية.","active":true},{"id":"excel","title":"Excel المتقدم للمهندسين والإداريين","title_en":"Advanced Excel for Engineers & Managers","category":"data","level":"مبتدئ","hours":14,"description":"الدوال المتقدمة والجداول المحورية والتحقق من البيانات والتقارير الآلية.","active":true},{"id":"n8n","title":"أتمتة الأعمال بـ n8n ووكلاء الذكاء الاصطناعي","title_en":"Business Automation with n8n & AI Agents","category":"tech","level":"متوسط","hours":16,"description":"تصميم سير عمل لأتمتة البريد والتقارير وخدمة العملاء وربط التطبيقات.","active":true},{"id":"leadership","title":"القيادة والإدارة الفعالة للفرق","title_en":"Leadership & Effective Team Management","category":"management","level":"مبتدئ","hours":12,"description":"التخطيط وتفويض المهام والتواصل الفعال وإدارة الأداء.","active":true}]'::jsonb) on conflict (setting_key) do nothing;
